#define TAU 6.28318


float WhiteNoise(vec2 p)
{
    return fract(sin(p.x*230.+p.y*670.)*5647.);
}

float ValueNoise(vec2 UV)
{
    float Bottom; float BottomLeft; float BottomRight;
    float Top; float TopLeft; float TopRight;  
    vec2 ID;

    ID = floor(UV);
    UV = fract(UV);

    UV = smoothstep(0.,1.,UV);

    BottomLeft = WhiteNoise(ID);
    BottomRight = WhiteNoise(ID+vec2(1., 0.));
    Bottom = mix(BottomLeft, BottomRight, UV.x);

    TopLeft = WhiteNoise(ID+vec2(0., 1.));
    TopRight = WhiteNoise(ID+vec2(1., 1.));
    Top = mix(TopLeft, TopRight, UV.x);

    return mix(Bottom, Top, UV.y);   
}


float FractalValueNoise( vec2 UV, float Scale, int Octaves )
{
    // Variable Declarations
    float Cg;    
    vec2 ID; 

    UV *= Scale;

    // Psuedo FBM
    float Frequency = 1.;
    float Amplitude = 1.;
    float Norm = Amplitude;

    for(int i = 0; i < Octaves; i++)
    { 
        float Offset = float(i/Octaves)*3.;
        Cg += ValueNoise( UV*(Frequency + Offset)) * Amplitude;
        Frequency *= 2.;
        Amplitude /= 2.;
        Norm += Amplitude;
    }

    Cg /= Norm;
    return Cg;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Declarations
    vec3 Cd;
    vec2 UV;  vec2 Rot;
    float Angle; float Size;
    float Distance; float Tiling;

    float Distort; float Noise; float Scale; 
    int Octave;

    float Wave; float WaveGradient;
    float SmoothWave;
    float WaveCoord;float WaveID; 

    float WaveSpeed; float WindSpeed;

    float Midpoint; float Min; float Max; 
    float WavePhase; float WaveAlpha;

    float OceanMask; 

    float Beach; float Wetness; 
    float WetSand; float DrySand;

    vec3 Water;vec3 Sand;
    float Darken;  

    float Shadow; float Foam;


    // Definitions
    Water = vec3(0.222831, 0.627296, 0.917);
    Sand = vec3(0.917, 0.451084, 0.189819);
    Darken = .4;

    Midpoint = .55;
    Size = .4;

    WaveSpeed = .2;
    WindSpeed = .125;

    WaveAlpha = 1.-fract(((iTime*WaveSpeed)-WaveSpeed)+.5);
    WavePhase = (sin(iTime*WaveSpeed*TAU)+1.)*0.5;

     // Normalized Pixel Coordinates with Aspect Ration (from 0 to 1)
    UV = fragCoord/iResolution.xy;

    UV.y = 1.0 - UV.y;

    Scale = 4.;
    Octave = 2;
    Noise = FractalValueNoise(UV, Scale, Octave);

    // UV -1 to 1
    UV -= .5; UV *= 2.;

    //Distort
    Distort = .4;
    UV = mix(UV, UV*Noise, Distort);

    Angle = 0.632;
    Angle *= TAU;
    Rot = vec2(cos(Angle), sin(Angle));

    Distance = dot(UV, Rot);

    // Distance 0 to 1
    Distance += 1.; Distance /=2.;

    Max = Size;
    Max /= 2.;

    Min = Midpoint-Max;
    Max += Midpoint;

    OceanMask = smoothstep(0.0, 0.3, Distance-(Min-.125));     
    Wave = Distance-mix(Min, Max, WavePhase);
    SmoothWave = smoothstep(0.01, 0., Wave);

    WaveGradient = fract(Wave);
    Tiling = 9.;

    float a; float b; float c;
     a = WaveGradient + (WaveAlpha*WindSpeed);
     b = a*mix(1.,Tiling, WaveAlpha);
     c = a*b;

    WaveCoord = fract(c);
    WaveID = floor(c)/Tiling;

    // Beach Offset
    Beach = 0.0;
    // Beach Gradient
    Wetness = 0.1;

    DrySand = Distance - (Beach + Max);
    DrySand = smoothstep(0., .2, DrySand);

    WetSand = Distance - ((Beach - Wetness) + Max);
    WetSand = smoothstep(0., Wetness, WetSand); 

    Sand = mix(Sand*Darken,Sand,DrySand);
    Sand = mix(Sand*Darken,Sand,WetSand);

    Water *= mix(.4, WaveID*SmoothWave, OceanMask);
    Water = mix(Sand, Water, smoothstep(.9,1., SmoothWave));

    Shadow = mix(WaveGradient, mix(WaveGradient, WaveCoord, SmoothWave), OceanMask);
    Shadow = smoothstep(0.,.1,Shadow);

    Foam = mix(0., WaveCoord*SmoothWave, OceanMask);
    Foam = (.45, .6, Foam);
    float Shore = SmoothWave-smoothstep(.01,0.,Wave+.15);
    Shore = smoothstep(.9,1., Shore);
    Foam += Shore;

    Cd = mix(Water*Shadow, vec3(1.), Foam);
    //Cd = vec3(Noise); 

    // Output to Screen
    fragColor = vec4(Cd,1.0);
}
